40	/**
41	 * Always HH:MM:SS, hours zero-padded to two digits and free to pass 99 for long totals.
42	 * `formatDuration` in conversation_duration.ts is deliberately not reused: it drops hours below one
43	 * hour, does not pad them, and sits on the chat timer's hot path.
44	 */
45	export function formatDurationHms(milliseconds: number) {
46	    const totalSeconds = Math.max(Math.floor(milliseconds / 1_000), 0);
47	    const hours = Math.floor(totalSeconds / 3_600);
48	    const minutes = Math.floor((totalSeconds % 3_600) / 60);
49	    const seconds = totalSeconds % 60;
50	
51	    return [hours, minutes, seconds].map((part) => String(part).padStart(2, '0')).join(':');
52	}
